#!/usr/bin/env bash
set -euo pipefail

mode="${1:?Specify standalone or snap}"
case "$mode" in
  standalone|snap) ;;
  *) echo "Unknown audio decoder environment: $mode" >&2; exit 2 ;;
esac

# Direct HTTPS streams are fed to the runtime's own appsrc URI handler.
if [[ "$mode" == standalone ]]; then
  gst-inspect-1.0 appsrc >/dev/null
else
  snap run --shell busymark -c '"$SNAP/usr/bin/gst-inspect-1.0" appsrc >/dev/null'
fi

# The strict application can read fixtures from this non-hidden directory
# through its home interface. Every file here is generated by this process.
work="$(mktemp -d "$HOME/busymark-audio-XXXXXXXX")"
trap 'rm -rf -- "$work"' EXIT
formats=(mp3 wav vorbis.ogg opus.ogg flac aac m4a webm)
encoders=(libmp3lame pcm_s16le libvorbis libopus flac aac aac libopus)
for index in "${!formats[@]}"; do
  name="${formats[$index]}"
  source="$work/sample.$name"
  pcm="$work/decoded.wav"
  ffmpeg -hide_banner -loglevel error -f lavfi \
    -i 'sine=frequency=440:duration=1:sample_rate=48000' \
    -c:a "${encoders[$index]}" "$source"
  if [[ "$mode" == standalone ]]; then
    timeout 20s gst-launch-1.0 -q filesrc "location=$source" ! decodebin \
      ! audioconvert ! audio/x-raw,format=S16LE ! wavenc ! filesink "location=$pcm"
  else
    # Create positional arguments safely without substituting file names into
    # interpreted shell code. snap passes the arguments to its -c shell.
    timeout 20s snap run --shell busymark -c '
      set -eu
      "$SNAP/usr/bin/gst-launch-1.0" -q filesrc "location=$1" ! decodebin \
        ! audioconvert ! audio/x-raw,format=S16LE ! wavenc ! filesink "location=$2"
    ' busymark-audio-decode "$source" "$pcm"
  fi
  /usr/bin/python3 - "$pcm" "$name" <<'PY'
import math
import struct
import sys
import wave

with wave.open(sys.argv[1]) as result:
    duration = result.getnframes() / result.getframerate()
    assert 0.90 <= duration <= 1.10, (sys.argv[2], duration)
    assert result.getsampwidth() == 2
    samples = struct.iter_unpack("<h", result.readframes(result.getnframes()))
    energy = 0
    crossings = 0
    negative_half_cycle = False
    count = 0
    for (sample,) in samples:
        energy += sample * sample
        if sample < -200:
            negative_half_cycle = True
        elif sample > 200 and negative_half_cycle:
            crossings += 1
            negative_half_cycle = False
        count += 1
    rms = math.sqrt(energy / count)
    frequency = crossings / duration
    assert 100 <= rms <= 16384, (sys.argv[2], rms)
    assert 410 <= frequency <= 470, (sys.argv[2], frequency)
    print(f"{sys.argv[2]} decoded {duration:.3f} s, {frequency:.1f} Hz, RMS {rms:.0f}")
PY
  rm -- "$pcm"
done
